ls -la /var/opt/mgu-uplink /var/opt/mgu-uplink/current/ 2>&1 | head -40; cat /etc/systemd/system/mgu-uplink.service; cat /etc/systemd/system/mgu-uplink.service.d/* 2>/dev/null; echo ---CFG; ps | grep "mgu-uplink run" | grep -v grep; for f in /var/opt/mgu-uplink/*.json /var/opt/mgu-uplink/current/*.json /var/opt/mgu-uplink/config*; do [ -f "$f" ] && { echo "== $f"; sed -E "s/(\"(psk|password|pass|key)\" *: *\")[^\"]*/\1***/g" "$f" | head -60; }; done; echo ---UPTIME; uptime; echo ---LOG; journalctl -u mgu-uplink -b --no-pager -o short-iso 2>&1 | tail -80 | cut -c1-260
